      "A river with two bridges, and an enemy line dug in across it. Tap a card, then tap your own half of the field: that hero rolls itself to the nearest bridge and picks its own fights. Mana refills on its own and every card shows what it costs. Two cards do not move at all: the Missile Launcher fires clear across the water but is blind up close, and the Pillbox is a hard point you plant where you expect the push. Hold either one and the field shows you its reach before you commit it. One battle, three minutes. They resupply faster every minute, and in the final minute BOTH sides refill at double rate, so the last sixty seconds are a flood. Raze their HQ to take the river outright. Lose your own and it is over; run the clock out and it is judged on ground taken. Kills pay, damage to their towers pays, and a fast HQ kill banks the clock.",
