    guideNext: "Next step",
    gs1Title: "Welcome",
    gs1Body:
      "A free season game built on real internet domains. Enlisting is one wallet signature: no transaction, no gas, and nothing in your wallet can move. Valor are just points. More points, bigger share of the pot the keeps unlock at season end.",
    gs1Cta: "Enlist free",
    gs2Title: "Get armed",
    gs2Body:
      "Holding takes $5 or more on the Doma app. The card road: sign in with Google, top up with a card or Apple Pay. The crypto road: bridge USDC over the prefilled Stargate link. The funding wizard in your HQ walks either road step by step.",
    gs2Cta: "Open the funding wizard",
