    faq1Link: "Guide here",
    faq2Q: "What does $5 actually buy?",
    faq2A: "A real piece of a featured domain token on Doma.",
    faq2Link: "How buying works",
    faq2B: "Holding it earns Valor daily and puts your hero on the map.",
    faqDomaQ: "What is Doma?",
    faqDomaA:
      "A domain marketplace where these names trade as tokens. When you buy in, you are buying a real piece of a real domain.",
    faq3Q: "How do the payouts work?",
    faq3A:
      "Every keep is worth a slice of the season pool, sized by difficulty, and unlocks its slice by the percent of the way it got: reclaimed unlocks it in full, half way unlocks half, and what no keep reached stays locked and is never paid. Up to $100 of that locked money pays the arcade prize. Your cut is the share of everyone's Valor you earned holding. Nothing is a lottery.",
