      intro:
        "전선 위를 수직으로 내려다보며 비행하는 3구간 출격입니다. 지상이 아래에서 위로 흘러옵니다. 아무 곳이나 길게 누르면 손가락 쪽으로 좌우 이동하고, 떼면 토크 롤이 기체를 왼쪽으로 끌고 갑니다. 전방 기관총은 위쪽의 목표를 향해 자동으로 발사되므로 비행 자체가 곧 사격입니다. 한 번 탭하면 폭탄을 투하하는데, 기수 앞에 떠 있는 황색 조준점 자리에 떨어집니다. 조준점을 영웅에 맞추고 누르세요. 점수는 폭탄에서 나옵니다. 기관총은 거의 값이 안 됩니다. 대공포는 당신이 향하는 지점을 조준하니 방향을 되돌리세요. 전투기는 위에서 편대로 강하하고, 뒤에서 상승해 꼬리에 붙습니다. 일부는 좌우로 흔들며 파고들어옵니다. 네 번 맞으면 추락하고, 공중에서 부딪히면 한 번에 두 대 분량입니다. 격추한 적은 보급을 떨어뜨립니다. 연료, 강화 기관총, 내구를 하나 돌려주는 수리 키트, 그리고 일시적인 속사입니다. 한 구간을 살아남으면 보너스를 챙기세요. 3구간 뒤에는 활주로를 지키는 기함 기지가 있으니 폭격으로 무너뜨리고, 최종 접근 구간을 버텨 착륙하세요.",
