      "게임과 레이드, 게시물은 골드와 함께 보유를 결코 넘지 못하는 소량의 일일 무훈을 줍니다. 해제된 금액은 모두 하나의 통에 모이고, 전체 무훈 대비 내 무훈 비율만큼이 내 몫이 됩니다. 현금 분배는 서로 다른 3일 이상 $5 이상 보유해야 하며, 이는 봇을 걸러내기 위한 확인일 뿐입니다. 통에서 당신이 받는 비중은 무훈에 따라 달라지므로, 우리는 풀에서 정해진 금액을 준다고 약속하지 않습니다. 아케이드 상금은 다릅니다: 네 게임마다 시즌 최고 기록 점수에 $25가 지급되며, 성채들이 끝내 얻지 못한 돈에서 나오고, 로그인한 지갑이면 누구나 받을 수 있습니다.",
