    domaCard1Title: "域名变成代币",
    domaCard1Body:
      "Doma 把真实的域名注册商接入一条为域名而建的区块链。域名照常作为网址工作，同时获得链上代币。碎片化(fractionalize)会把那枚所有权代币锁进 Doma 合约，并发行固定数量的小份代币，让许多人各持一份。",
    domaCard2Title: "在哪里买",
    domaCard2Body:
      "就在这里买：在地图上点任意一座进行中的堡垒，选 $1 起的金额，授权一次，几秒后代币就到你的钱包里。使用 Doma 链上的 USDC.e 付款。需要充值就在 app.doma.xyz 用 Google 登录，用银行卡或 Apple Pay 充值；也可以用预填好的 Stargate 链接把 USDC 跨链过来，用自己的钱包买入。无论哪条路，代币都在你的钱包里，从不在我们手上。",
    domaCard3Title: "攻破 (BREACHED) 到底是什么",
    domaCard3Body:
      "新的域名代币从带绑定曲线的启动台起步，那是一条起价和终价固定的资金进度条。当买入填满进度条，代币就毕业上链，进入公开流动性池。那次毕业就是这个游戏所说的攻破，也是堡垒全额份额解锁的时刻。",
    domaCard4Title: "如果有人整个买下域名",
    domaCard4Body:
      "域名本身可以在链上被整体买断，买断价内置防操纵保护。真发生时，代币持有者可以把代币赎回成稳定币。玩这个游戏完全用不到这些，但游戏脚下的地面就是这样运转的。",
